{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Tetrabenazine showed very low mean oral systemic availability of 0.049 ± 0.032 in patients, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Felodipine absolute oral bioavailability was 15.3% in fasted volunteers, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Tegaserod mean absolute bioavailability was approximately 10% in healthy volunteers, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Delmopinol bioavailability after oral administration was reported as very low.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Colesevelam systemic bioavailability was <0.04%, indicating negligible oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Nimodipine mean oral bioavailability was 15.9% (median 15.0%), below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Testosterone undecanoate, a highly lipophilic long-chain ester prodrug, had mean absolute oral bioavailability of 6.8 ± 3.3% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Batimastat showed poor oral bioavailability in humans, consistent with low systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate, another long-chain lipophilic ester, showed poor and inconsistent oral bioavailability in men.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Nitrendipine absolute bioavailability was 10.7 ± 4.7% after a 20 mg oral tablet, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "One nitrendipine report gave 40% oral bioavailability in normal subjects, but this is an isolated outlier from a structurally unrelated dihydropyridine and does not transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a GI-targeted lipase inhibitor with negligible systemic absorption; all transferable evidence from lipophilic ester/lactone and poorly absorbed drugs points to oral bioavailability far below 20%.",
  "evidence_gaps": [
    "No direct orlistat-specific absolute bioavailability measurement is present in the supplied records.",
    "Most records are from structurally unrelated scaffolds; the closest analogs are long-chain lipophilic esters with low bioavailability.",
    "A few nitrendipine reports exceed 20%, but they are not mechanistically or structurally relevant to orlistat."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

